import {jest} from '@jest/globals';
import net from 'node:net';
import {setLogger} from '../shared/logger.js';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {ExtWebSocket} from './ws/connectionHandler.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {WsAuthenticator} from '../types/auth.js';

// The defect this pins is an omission: both hooks are declared on HalServerOptions, and one was never forwarded.

const settle = () => new Promise<void>(resolve => setTimeout(resolve, 0));

const harness = (onConnect?: (session: ChatSession) => void) => {
  const sessionStore = {
    create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
    delete: () => true,
  } as unknown as SessionStore;

  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: jest.fn() as unknown as WsAuthenticator,
    sessionStore,
    orchestrator: {} as ChatOrchestrator,
    onConnect,
  });

  const ws = {
    userId: 'u1',
    isAlive: true,
    send: () => undefined,
    on: () => undefined,
    // The handler pauses the socket across an awaited create and resumes once its listeners are attached.
    pause: () => undefined,
    resume: () => undefined,
    close: () => undefined,
  } as unknown as ExtWebSocket;

  return {hal, ws};
};

describe('createServer hook wiring', () => {
  it('forwards onConnect to the connection handler', async () => {
    const seen: ChatSession[] = [];
    const {hal, ws} = harness(session => void seen.push(session));

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(seen.length).toBe(1);
  });

  it('accepts a server configured without either hook', async () => {
    const {hal, ws} = harness();

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(hal.wss.listenerCount('connection')).toBe(1);
  });
});

// An EventEmitter with no `error` listener throws, so a socket error on a running server ended the process.
describe('a server error after start', () => {
  const engineLines: string[] = [];

  beforeEach(() => {
    engineLines.length = 0;
    const collect = (_category: string, message: string) => void engineLines.push(message);
    setLogger({debug: collect, info: collect, warn: collect, error: collect});
  });

  afterEach(() => {
    setLogger();
  });

  const started = async () => {
    const {hal} = harness();
    await hal.start(0);
    return hal;
  };

  // A stopped engine and a port something else holds, so the next start is refused by the OS.
  const refusedStart = async () => {
    const hal = await started();
    await hal.stop();
    const blocker = net.createServer();
    await new Promise<void>(resolve => blocker.listen(0, resolve));
    const taken = (blocker.address() as net.AddressInfo).port;
    const release = () => new Promise<void>(resolve => blocker.close(() => resolve()));
    return {hal, taken, release};
  };

  it('is reported rather than ending the process', async () => {
    const hal = await started();

    hal.server.emit('error', new Error('late failure'));
    await hal.stop();

    expect(engineLines).toContain('server error after start');
  });

  it('leaves exactly one listener behind, however many times the server is restarted', async () => {
    const hal = await started();
    await hal.stop();
    await hal.start(0);

    const count = hal.server.listenerCount('error');
    await hal.stop();

    expect(count).toBe(1);
  });

  it('is still reported after stop, because an error with no handler ends the process', async () => {
    const hal = await started();
    await hal.stop();

    hal.server.emit('error', new Error('after stop'));

    expect(engineLines).toContain('server error after start');
  });

  it('is not reported for a start that was cleanly refused, because nothing was running', async () => {
    const {hal, taken, release} = await refusedStart();

    await hal.start(taken).catch((error: NodeJS.ErrnoException) => engineLines.push(`rejected ${error.code}`));
    await release();

    expect(engineLines).toEqual(['HAL Engine started', 'rejected EADDRINUSE']);
  });

  it('stops cleanly after a refused start, so a finally block does not turn one failure into two', async () => {
    const {hal, taken, release} = await refusedStart();
    await hal.start(taken).catch(() => undefined);

    const stopped = hal.stop().then(
      () => 'resolved',
      (error: NodeJS.ErrnoException) => `rejected ${error.code}`
    );
    await release();

    await expect(stopped).resolves.toBe('resolved');
  });

  it('refuses a second start without stripping the running server of its handler', async () => {
    const hal = await started();

    await hal.start(0).catch((error: Error) => engineLines.push(`rejected ${error.message}`));
    hal.server.emit('error', new Error('after the refused start'));
    await hal.stop();

    expect(engineLines).toEqual([
      'HAL Engine started',
      'rejected HAL Engine is already started',
      'server error after start',
    ]);
  });
});
import {jest} from '@jest/globals';
import {createConnectionHandler, type ConnectionHandlerDeps, type ExtWebSocket} from './connectionHandler.js';
import type {ChatSession} from '../../types/session.js';
import type {SessionStore} from '../../types/sessionStore.js';
import {captureErrors} from '../../shared/logCaptureTestSupport.js';

// Pins the lifecycle hooks: that onConnect is called at all, when, and that neither hook can kill a connection.

// Drains the microtask queue the hook is deferred onto.
const settle = () => new Promise<void>(resolve => setTimeout(resolve, 0));

type HarnessOptions = Partial<Pick<ConnectionHandlerDeps, 'onConnect' | 'onDisconnect' | 'sessionStore'>>;

const harness = (options: HarnessOptions = {}) => {
  const sent: string[] = [];
  const listeners = new Map<string, (arg?: unknown) => void>();

  const ws = {
    userId: 'u1',
    isAlive: true,
    send: (raw: string) => sent.push(raw),
    on: (event: string, fn: (arg?: unknown) => void) => listeners.set(event, fn),
    // The handler pauses the socket across an awaited create and resumes once its listeners are attached.
    pause: () => undefined,
    resume: () => undefined,
    close: () => undefined,
  } as unknown as ExtWebSocket;

  const deleted: string[] = [];
  const sessionStore = {
    create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
    delete: (sessionId: string) => (deleted.push(sessionId), true),
  } as unknown as SessionStore;

  const deps = {
    wsAuth: jest.fn(),
    sessionStore,
    handleMessage: jest.fn(),
    basePath: '/hal',
    ...options,
  } as unknown as ConnectionHandlerDeps;

  const connect = () => createConnectionHandler(deps, [])(ws);

  return {
    connect,
    sent,
    deleted,
    handleMessage: deps.handleMessage as jest.Mock,
    close: () => listeners.get('close')?.(),
    receive: (frame: string) => listeners.get('message')?.(frame),
  };
};

describe('the websocket connection handler', () => {
  describe('onConnect', () => {
    it('is called once for an accepted connection, with the session the socket was given', async () => {
      const seen: ChatSession[] = [];
      const {connect, sent} = harness({onConnect: session => void seen.push(session)});

      connect();
      await settle();

      const frame = JSON.parse(sent[0]) as {type: string; sessionId: string};
      expect({calls: seen.length, sessionId: seen[0]?.sessionId}).toEqual({calls: 1, sessionId: frame.sessionId});
    });

    // A REST chat id is not a socket session id: the socket mints its own, so neither can be guessed
    it('mints a fresh session id per connection rather than reusing one', async () => {
      const first = harness();
      const second = harness();

      first.connect();
      second.connect();
      await settle();

      const id = (raw: string) => (JSON.parse(raw) as {sessionId: string}).sessionId;
      expect(id(first.sent[0]) === id(second.sent[0])).toBe(false);
    });

    // Counted inside the hook: the connected frame is sent after an awaited create, so no synchronous read sees it.
    it('runs after the connected frame is sent, not before it', async () => {
      const framesAtHook: number[] = [];
      let frames: string[] = [];
      const {connect, sent} = harness({onConnect: () => void framesAtHook.push(frames.length)});
      frames = sent;

      connect();
      await settle();

      expect(framesAtHook).toEqual([1]);
    });

    it('is deferred, so it never runs inside the connection listener', () => {
      const order: string[] = [];
      const {connect} = harness({onConnect: () => void order.push('hook')});

      connect();

      expect(order).toEqual([]);
    });

    it('survives a hook that throws synchronously', async () => {
      const {connect} = harness({
        onConnect: () => {
          throw new Error('hook exploded');
        },
      });

      connect();

      await expect(settle()).resolves.toBeUndefined();
    });

    it('survives a hook that rejects', async () => {
      const {connect} = harness({onConnect: () => Promise.reject(new Error('hook rejected'))});

      connect();

      await expect(settle()).resolves.toBeUndefined();
    });

    it('is optional, so a connection without one still sends its frame', async () => {
      const {connect, sent} = harness();

      connect();
      await settle();

      expect(sent.length).toBe(1);
    });
  });

  describe('onDisconnect', () => {
    // The close path erases nothing now, so the hook is the only thing a consumer can hang cleanup on.
    it('is called with the session id while the store still holds the session', async () => {
      const seen: string[] = [];
      const {connect, sent, close, deleted} = harness({onDisconnect: id => void seen.push(id)});

      connect();
      await settle();
      const {sessionId} = JSON.parse(sent[0]) as {sessionId: string};
      close();
      await settle();

      expect({seen, deleted}).toEqual({seen: [sessionId], deleted: []});
    });

    it('does not let a throwing hook escape the close listener', () => {
      const {connect, close} = harness({
        onDisconnect: () => {
          throw new Error('hook exploded');
        },
      });
      connect();

      expect(() => close()).not.toThrow();
    });

    it('does not let a rejecting hook reach the process', async () => {
      const {connect, close} = harness({onDisconnect: () => Promise.reject(new Error('hook rejected'))});
      connect();

      close();

      await expect(settle()).resolves.toBeUndefined();
    });
  });

  describe('the connection signal', () => {
    it('hands every message on a connection the same signal, and each connection its own', async () => {
      const first = harness();
      const second = harness();
      first.connect();
      second.connect();
      await settle();

      first.receive(JSON.stringify({type: 'ping', timestamp: 1}));
      first.receive(JSON.stringify({type: 'ping', timestamp: 2}));
      second.receive(JSON.stringify({type: 'ping', timestamp: 3}));

      const {calls: firstCalls} = first.handleMessage.mock;
      const {calls: secondCalls} = second.handleMessage.mock;
      const [one, two, other] = [...firstCalls, ...secondCalls].map(call => call[3]);
      expect({isSignal: one instanceof AbortSignal, shared: one === two, own: one !== other}).toEqual({
        isSignal: true,
        shared: true,
        own: true,
      });
    });

    it('aborts the connection signal when its socket closes, before onDisconnect is called', async () => {
      const abortedAtDisconnect: unknown[] = [];
      const handed: {signal?: AbortSignal} = {};
      const {connect, receive, close, handleMessage} = harness({
        onDisconnect: () => void abortedAtDisconnect.push(handed.signal?.aborted),
      });
      connect();
      await settle();
      receive(JSON.stringify({type: 'ping', timestamp: 1}));
      const {calls} = handleMessage.mock;
      handed.signal = calls[0]?.[3] as AbortSignal | undefined;
      const beforeClose = handed.signal?.aborted;

      close();

      expect({beforeClose, abortedAtDisconnect}).toEqual({beforeClose: false, abortedAtDisconnect: [true]});
    });
  });

  describe('inbound frames', () => {
    it('answers unparseable JSON with INVALID_FORMAT alone and never dispatches it', async () => {
      const {connect, sent, receive, handleMessage} = harness();
      connect();
      // The message listener is attached once the awaited create resolves.
      await settle();

      receive('{"type": "user_message", "content": ');

      const types = sent.slice(1).map(raw => (JSON.parse(raw) as {type: string; code?: string}).code ?? 'no code');
      const {calls} = handleMessage.mock;
      expect({afterConnected: types, dispatched: calls.length}).toEqual({
        afterConnected: ['INVALID_FORMAT'],
        dispatched: 0,
      });
    });
  });
});

